function paySheet(body,name){sheet('Pay '+name,'<p>Amount: <b>'+money(body.amount)+'</b></p><form id="mPayForm" class="m-form"><label for="mPayMethod">Payment method</label><select id="mPayMethod">'+option('mobile_money','Mobile Money')+option('card','Card')+option('paystack','Bank / Other options')+'</select><button class="m-btn" type="submit">Continue to secure checkout</button></form>');E('mPayForm').onsubmit=async function(event){event.preventDefault();if(state.saving)return;var btn=this.querySelector('button');btn.disabled=true;try{var result=await api('/api/parent/payment-intents',{...body,method:E('mPayMethod').value});if(!result.authorization_url)throw Error('The payment provider did not return a checkout link.');var url=new URL(result.authorization_url);if(url.protocol!=='https:')throw Error('The checkout link is invalid.');sessionStorage.setItem('rx_mobile_payment_reference',result.reference);closeSheet();location.href=url.href}catch(error){btn.disabled=false;toast(error.message,true)}}}
async function checkPayment(){var reference=sessionStorage.getItem('rx_mobile_payment_reference');if(!reference)return;try{var result=await api('/api/parent/payment-intents/'+encodeURIComponent(reference)+'/status');if(result.status==='success'){sessionStorage.removeItem('rx_mobile_payment_reference');toast('Payment confirmed. Your school balance has been updated.');go('fees',null,true)}else if(['failed','cancelled','abandoned','reversed'].includes(result.status)){sessionStorage.removeItem('rx_mobile_payment_reference');toast(result.failureReason||'Payment was not completed.',true);go('fees',null,true)}else toast('The payment is still being confirmed. Please wait before paying again.')}catch(error){toast(error.message,true)}}
