export function mobileExperienceFrontend(role:'teacher'|'parent'){
 return `<!doctype html><html lang="en"><head>${head}<title>Revolt School · ${role==='teacher'?'Teacher':'Parent'}</title></head><body data-mobile-role="${role}"><div id="mApp" class="m-app"><div id="mOffline" class="m-offline" role="status" hidden>You are offline. Your unsaved entries stay here until you reconnect.</div><header class="m-header"><img src="/school-icon-192.png" class="m-brand-icon" alt=""><div class="m-brand">Revolt School<small id="mSchoolName">${role==='teacher'?'Teacher app':'Parent app'}</small></div><button id="mHeaderAction" type="button" class="m-icon-button" aria-label="School updates" hidden><svg class="m-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 17h14l-2-4V8a5 5 0 0 0-10 0v5zM10 21h4"/></svg></button></header><main id="mView" class="m-view"></main><nav id="mDock" class="m-dock" aria-label="Main navigation" hidden></nav></div><div id="mDialog" class="m-dialog" hidden><section id="mSheet" class="m-sheet" role="dialog" aria-modal="true" aria-labelledby="mSheetTitle"></section></div><div id="mToast" class="m-toast" role="status" aria-live="polite" hidden></div><script>${schoolSessionScript(role)}${schoolSignInStartupScript}${mobileWorkflowScript}</script><script src="/school-native.js?v=${mobileExperienceVersion}" defer></script></body></html>`;
}
